import json
from pathlib import Path

from hypothesis import given
from hypothesis import strategies as st

import orderbooks.bench_ci

_MEANS = st.lists(
    st.floats(min_value=0, exclude_min=True, allow_infinity=False), min_size=1
)
_CONFIDENCE = st.floats(min_value=0, max_value=1, exclude_min=True, exclude_max=True)


@given(values=_MEANS, confidence=_CONFIDENCE)
def test_fuzz_interval(values: list[float], confidence: float) -> None:
    orderbooks.bench_ci.interval(values=values, confidence=confidence)


@given(base=_MEANS, new=_MEANS, confidence=_CONFIDENCE)
def test_fuzz_ratio_interval(
    base: list[float], new: list[float], confidence: float
) -> None:
    orderbooks.bench_ci.ratio_interval(base=base, new=new, confidence=confidence)


@given(
    table=st.dictionaries(
        keys=st.text(),
        values=st.dictionaries(keys=st.text(), values=_MEANS, min_size=1),
    ),
    confidence=_CONFIDENCE,
)
def test_fuzz_report(
    table: dict[str, dict[str, list[float]]], confidence: float
) -> None:
    orderbooks.bench_ci.report(table=table, confidence=confidence)


def test_read_run_averages_iterations(tmp_path: Path) -> None:
    def entry(run_name: str, aggregate: str, real_time: float) -> dict[str, object]:
        return {
            "name": f"{run_name}_{aggregate}" if aggregate else run_name,
            "run_name": run_name,
            "run_type": "aggregate" if aggregate else "iteration",
            "real_time": real_time,
        }

    report = {
        "benchmarks": [
            entry("BM_x/8", "", 1.0),
            entry("BM_x/8", "", 3.0),
            entry("BM_x/64", "", 10.0),
            entry("BM_x/64", "", 30.0),
            entry("BM_x/8", "mean", 2.0),
            entry("BM_x/8", "cv", 0.5),
        ]
    }
    path = tmp_path / "base-1.json"
    path.write_text(json.dumps(report), encoding="utf-8")
    assert orderbooks.bench_ci.read_run(path, "real_time") == (
        "base",
        {"BM_x/8": 2.0, "BM_x/64": 20.0},
    )
